  --color-gray-200: #E9E7E3;
  --color-gray-300: #D1CEC8;
  --color-gray-400: #B4AFA7;
  --color-gray-500: #8E8780;
  --color-gray-600: #6B665F;
  --color-gray-700: #4D4842;
  --color-gray-800: #2E2B27;
  --color-gray-900: #1A1816;

  /* Preto */
  --color-black: #0D0C0B;

  /* === TIPOGRAFIA === */
  --font-serif: 'Cormorant Garamond', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Tamanhos */
  --text-xs: 0.75rem;      /* 12px */
  --text-sm: 0.875rem;     /* 14px */
  --text-base: 1rem;       /* 16px */
  --text-lg: 1.125rem;     /* 18px */
  --text-xl: 1.25rem;      /* 20px */
  --text-2xl: 1.5rem;      /* 24px */
  --text-3xl: 1.875rem;    /* 30px */
  --text-4xl: 2.25rem;     /* 36px */
  --text-5xl: 3rem;        /* 48px */
  --text-6xl: 3.75rem;     /* 60px */
  --text-7xl: 4.5rem;      /* 72px */

  /* Pesos */
  --font-light: 300;
  --font-normal: 400;
  --font-medium: 500;
  --font-semibold: 600;
  --font-bold: 700;

  /* === ESPAÇAMENTO === */
  --space-1: 0.25rem;   /* 4px */
  --space-2: 0.5rem;    /* 8px */
  --space-3: 0.75rem;   /* 12px */
  --space-4: 1rem;      /* 16px */
  --space-5: 1.25rem;   /* 20px */
  --space-6: 1.5rem;    /* 24px */
  --space-8: 2rem;      /* 32px */
  --space-10: 2.5rem;   /* 40px */
  --space-12: 3rem;     /* 48px */
  --space-16: 4rem;     /* 64px */
  --space-20: 5rem;     /* 80px */
  --space-24: 6rem;     /* 96px */
  --space-32: 8rem;     /* 128px */

  /* === BORDAS === */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;

  /* === TRANSIÇÕES === */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);

  /* === SOMBRAS === */
  --shadow-subtle: 0 1px 3px rgba(0, 0, 0, 0.04);
  --shadow-soft: 0 4px 12px rgba(0, 0, 0, 0.08);
  --shadow-medium: 0 8px 24px rgba(0, 0, 0, 0.12);
}

/* === RESET === */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  font-weight: var(--font-normal);
  line-height: 1.6;
  color: var(--color-gray-800);
  background-color: var(--color-off-white);
  overflow-x: hidden;
}

/* === TIPOGRAFIA === */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: var(--font-semibold);
  line-height: 1.2;
  color: var(--color-gray-900);
  margin: 0;
}

h1 {
  font-size: var(--text-5xl);
  font-weight: var(--font-semibold);
  letter-spacing: -0.02em;
}

h2 {
  font-size: var(--text-4xl);
  font-weight: var(--font-semibold);
}

h3 {
  font-size: var(--text-3xl);
  font-weight: var(--font-medium);
}

h4 {
  font-size: var(--text-2xl);
}

p {
  margin: 0;
  line-height: 1.7;
}

a {
  color: inherit;
  text-decoration: none;
  transition: opacity var(--transition-fast);
}

a:hover {
  opacity: 0.7;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* === UTILITIES === */

.container {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

@media (min-width: 768px) {
  .container {
    padding: 0 var(--space-12);
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 var(--space-16);
  }
}

.section {
  padding: var(--space-16) 0;
}

@media (min-width: 768px) {
  .section {
    padding: var(--space-24) 0;
  }
}

/* === RESPONSIVO === */

@media (max-width: 767px) {
  :root {
    --text-5xl: 2.25rem;  /* 36px */
    --text-4xl: 1.875rem; /* 30px */
    --text-3xl: 1.5rem;   /* 24px */
  }

  h1 {
    font-size: var(--text-4xl);
  }

  h2 {
    font-size: var(--text-3xl);
  }
}

/* === ANIMAÇÕES DE SCROLL === */

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in-up {
  animation: fadeInUp 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

/* === ACESSIBILIDADE === */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

:focus-visible {
  outline: 2px solid var(--color-wood);
  outline-offset: 4px;
}

/* === SELEÇÃO DE TEXTO === */

::selection {
  background-color: var(--color-wood-light);
  color: var(--color-white);
}

