import React, { useState, useEffect } from 'react';
import { Search, Menu, X, Instagram } from 'lucide-react';
import './Header.css';

const Header = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 100);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [isMobileMenuOpen]);

  const navItems = [
    { label: 'Início', href: '#inicio' },
    { label: 'Móveis', href: '#moveis' },
    { label: 'Coleções', href: '#colecoes' },
    { label: 'Ambientes', href: '#ambientes' },
    { label: 'Sobre', href: '#sobre' },
    { label: 'Contato', href: '#contato' }
  ];

  const handleNavClick = (e, href) => {
    e.preventDefault();
    setIsMobileMenuOpen(false);

    const element = document.querySelector(href);
    if (element) {
      const offset = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  return (
    <header className={`header ${isScrolled ? 'header--scrolled' : ''}`}>
      <div className="header__container container">
        {/* Logo */}
        <a href="#inicio" className="header__logo" onClick={(e) => handleNavClick(e, '#inicio')}>
          <div className="header__logo-mark">AD</div>
          <div className="header__logo-text">
            <span className="header__logo-name">ARTEFER</span>
            <span className="header__logo-subtitle">DECOR</span>
          </div>
        </a>

        {/* Desktop Navigation */}
        <nav className="header__nav">
          {navItems.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="header__nav-link"
              onClick={(e) => handleNavClick(e, item.href)}
            >
              {item.label}
            </a>
          ))}
        </nav>

        {/* Right Actions */}
        <div className="header__actions">
          <a
            href="https://instagram.com/artefer_decor_"
            target="_blank"
            rel="noopener noreferrer"
            className="header__action-btn"
            aria-label="Instagram da Artefer Decor"
          >
            <Instagram size={20} />
          </a>

          <a
            href="#contato"
            className="header__cta"
            onClick={(e) => handleNavClick(e, '#contato')}
          >
            Fale conosco
          </a>

          {/* Mobile Menu Button */}
          <button
            className="header__mobile-toggle"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            aria-label={isMobileMenuOpen ? 'Fechar menu' : 'Abrir menu'}
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`header__mobile-menu ${isMobileMenuOpen ? 'header__mobile-menu--open' : ''}`}>
        <nav className="header__mobile-nav">
          {navItems.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="header__mobile-link"
              onClick={(e) => handleNavClick(e, item.href)}
            >
              {item.label}
            </a>
          ))}
        </nav>

        <div className="header__mobile-contact">
          <a
            href="https://instagram.com/artefer_decor_"
            target="_blank"
            rel="noopener noreferrer"
            className="header__mobile-social"
          >
            <Instagram size={20} />
            <span>@artefer_decor_</span>
          </a>

          <a href="tel:+5532998085068" className="header__mobile-phone">
            (32) 99808-5068
          </a>
        </div>
      </div>
    </header>
  );
};

export default Header;

/* ============================================
   HEADER - Editorial & Sofisticado
   ============================================ */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  transition: background-color var(--transition-base),
              backdrop-filter var(--transition-base),
              box-shadow var(--transition-base);
}

.header--scrolled {
  background-color: rgba(250, 248, 245, 0.95);
  backdrop-filter: blur(12px);
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.06);
}

.header__container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
}

/* === LOGO === */

.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  transition: opacity var(--transition-fast);
}

.header__logo:hover {
  opacity: 1;
}

.header__logo-mark {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-gray-900);
  color: var(--color-off-white);
  font-family: var(--font-serif);
  font-size: var(--text-lg);
  font-weight: var(--font-semibold);
  letter-spacing: 0.02em;
}

.header__logo-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.header__logo-name {
  font-family: var(--font-serif);
  font-size: var(--text-xl);
  font-weight: var(--font-semibold);
  color: var(--color-gray-900);
  letter-spacing: 0.08em;
}

.header__logo-subtitle {
  font-family: var(--font-sans);
  font-size: var(--text-xs);
  font-weight: var(--font-normal);
  color: var(--color-gray-600);
  letter-spacing: 0.15em;
  margin-top: 2px;
}

/* === NAVEGAÇÃO DESKTOP === */

.header__nav {
  display: none;
  align-items: center;
  gap: var(--space-8);
}

@media (min-width: 1024px) {
  .header__nav {
    display: flex;
  }
}

.header__nav-link {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: var(--font-normal);
  color: var(--color-gray-700);
  letter-spacing: 0.02em;
  position: relative;
  padding: var(--space-2) 0;
  transition: color var(--transition-fast);
}

.header__nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--color-gray-900);
  transition: width var(--transition-base);
}

.header__nav-link:hover {
  color: var(--color-gray-900);
  opacity: 1;
}

.header__nav-link:hover::after {
  width: 100%;
}

/* === AÇÕES === */

.header__actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.header__action-btn {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
}

@media (min-width: 768px) {
  .header__action-btn {
    display: flex;
  }
}

.header__action-btn:hover {
  color: var(--color-gray-900);
  opacity: 1;
}

.header__cta {
  display: none;
  padding: var(--space-3) var(--space-6);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--color-off-white);
  background-color: var(--color-gray-900);
  border: 1px solid var(--color-gray-900);
  transition: background-color var(--transition-fast),
              color var(--transition-fast);
}

@media (min-width: 768px) {
  .header__cta {
    display: block;
  }
}

.header__cta:hover {
  background-color: transparent;
  color: var(--color-gray-900);
  opacity: 1;
}

/* === MOBILE MENU TOGGLE === */

.header__mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--color-gray-900);
  cursor: pointer;
}

@media (min-width: 1024px) {
  .header__mobile-toggle {
    display: none;
  }
}

/* === MOBILE MENU === */

.header__mobile-menu {
  position: fixed;
  top: 80px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-off-white);
  display: flex;
  flex-direction: column;
  padding: var(--space-8) var(--space-6);
  transform: translateX(100%);
  transition: transform var(--transition-base);
  overflow-y: auto;
}

@media (min-width: 1024px) {
  .header__mobile-menu {
    display: none;
  }
}

.header__mobile-menu--open {
  transform: translateX(0);
}

.header__mobile-nav {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-bottom: var(--space-12);
}

.header__mobile-link {
  font-family: var(--font-serif);
  font-size: var(--text-3xl);
  font-weight: var(--font-medium);
  color: var(--color-gray-900);
  padding: var(--space-3) 0;
  border-bottom: 1px solid var(--color-gray-200);
  transition: color var(--transition-fast);
}

.header__mobile-link:hover {
  color: var(--color-wood);
  opacity: 1;
}

.header__mobile-contact {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  margin-top: auto;
  padding-top: var(--space-8);
  border-top: 1px solid var(--color-gray-200);
}

.header__mobile-social {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  color: var(--color-gray-700);
}

.header__mobile-phone {
  font-family: var(--font-sans);
  font-size: var(--text-lg);
  font-weight: var(--font-medium);
  color: var(--color-gray-900);
}

