}

@media (min-width: 768px) {
  .header__cta {
    display: block;
  }
}

.header__cta:hover {
  background-color: transparent;
  color: var(--color-gray-900);
  opacity: 1;
}

/* === MOBILE MENU TOGGLE === */

.header__mobile-toggle {
