import React, { useState, useEffect } from 'react';
import { ArrowDown } from 'lucide-react';
import './Hero.css';

const Hero = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const scrollToContent = () => {
    const nextSection = document.querySelector('#destaque');
    if (nextSection) {
      const offset = 80;
      const elementPosition = nextSection.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  return (
    <section className="hero" id="inicio">
      <div className="hero__image">
        <div className="hero__image-overlay"></div>
        {/* Placeholder para imagem de ambiente sofisticado */}
        <img
          src="https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?w=1920&q=80"
          alt="Ambiente sofisticado Artefer Decor"
          className="hero__img"
        />
      </div>

      <div className="hero__content">
        <div className={`hero__text ${isVisible ? 'hero__text--visible' : ''}`}>
          <h1 className="hero__title">
            Móveis que transformam ambientes.
          </h1>
          <p className="hero__subtitle">
            Design, qualidade e personalidade para espaços que merecem ser únicos.
          </p>

          <div className="hero__actions">
            <a href="#colecoes" className="hero__btn hero__btn--primary">
              Conheça nossas coleções
            </a>
            <a
              href="https://wa.me/5532998085068?text=Olá!%20Gostaria%20de%20conhecer%20os%20móveis%20da%20Artefer%20Decor"
              target="_blank"
              rel="noopener noreferrer"
              className="hero__btn hero__btn--secondary"
            >
              Fale com a Artefer
            </a>
          </div>
        </div>

        <button
          className="hero__scroll-indicator"
          onClick={scrollToContent}
          aria-label="Rolar para o conteúdo"
        >
          <ArrowDown size={20} />
        </button>
      </div>
    </section>
  );
};

export default Hero;

/* ============================================
   HERO - Grande, Visual, Editorial
   ============================================ */

.hero {
  position: relative;
  height: 100vh;
  min-height: 600px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--color-gray-900);
}

/* === IMAGEM === */

.hero__image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.hero__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.hero__image-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0.2) 0%,
    rgba(0, 0, 0, 0.4) 100%
  );
  z-index: 2;
}

/* === CONTEÚDO === */

.hero__content {
  position: relative;
  z-index: 3;
  width: 100%;
  max-width: 1440px;
  padding: 0 var(--space-6);
  margin: 0 auto;
}

@media (min-width: 768px) {
  .hero__content {
    padding: 0 var(--space-12);
  }
}

@media (min-width: 1024px) {
  .hero__content {
    padding: 0 var(--space-16);
  }
}

.hero__text {
  max-width: 800px;
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 1s cubic-bezier(0.4, 0, 0.2, 1),
              transform 1s cubic-bezier(0.4, 0, 0.2, 1);
}

.hero__text--visible {
  opacity: 1;
  transform: translateY(0);
}

.hero__title {
  font-family: var(--font-serif);
  font-size: var(--text-5xl);
  font-weight: var(--font-semibold);
  line-height: 1.1;
  color: var(--color-white);
  margin-bottom: var(--space-6);
  letter-spacing: -0.02em;
}

@media (min-width: 768px) {
  .hero__title {
    font-size: var(--text-6xl);
  }
}

@media (min-width: 1024px) {
  .hero__title {
    font-size: var(--text-7xl);
  }
}

.hero__subtitle {
  font-family: var(--font-sans);
  font-size: var(--text-lg);
  font-weight: var(--font-light);
  line-height: 1.6;
  color: var(--color-off-white);
  margin-bottom: var(--space-10);
  max-width: 600px;
}

@media (min-width: 768px) {
  .hero__subtitle {
    font-size: var(--text-xl);
  }
}

/* === AÇÕES === */

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.hero__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4) var(--space-8);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  font-weight: var(--font-medium);
  letter-spacing: 0.01em;
  transition: all var(--transition-base);
  cursor: pointer;
  min-height: 52px;
}

.hero__btn--primary {
  background-color: var(--color-white);
  color: var(--color-gray-900);
  border: 1px solid var(--color-white);
}

.hero__btn--primary:hover {
  background-color: transparent;
  color: var(--color-white);
  opacity: 1;
}

.hero__btn--secondary {
  background-color: transparent;
  color: var(--color-white);
  border: 1px solid var(--color-white);
}

.hero__btn--secondary:hover {
  background-color: var(--color-white);
  color: var(--color-gray-900);
  opacity: 1;
}

/* === SCROLL INDICATOR === */

.hero__scroll-indicator {
  position: absolute;
  bottom: var(--space-8);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--color-white);
  cursor: pointer;
  animation: bounce 2s infinite;
  transition: opacity var(--transition-fast);
}

.hero__scroll-indicator:hover {
  opacity: 0.7;
}

@keyframes bounce {
  0%, 20%, 50%, 80%, 100% {
    transform: translateX(-50%) translateY(0);
  }
  40% {
    transform: translateX(-50%) translateY(-10px);
  }
  60% {
    transform: translateX(-50%) translateY(-5px);
  }
}

/* === RESPONSIVO === */

@media (max-width: 767px) {
  .hero {
    min-height: 500px;
  }

  .hero__btn {
    width: 100%;
    padding: var(--space-4) var(--space-6);
  }
}

import React from 'react';
import { Instagram, MapPin, Mail, Phone } from 'lucide-react';
import './Footer.css';

const Footer = () => {
  const currentYear = new Date().getFullYear();

  const navLinks = [
    { label: 'Início', href: '#inicio' },
    { label: 'Móveis', href: '#moveis' },
    { label: 'Coleções', href: '#colecoes' },
    { label: 'Ambientes', href: '#ambientes' },
    { label: 'Sobre', href: '#sobre' },
    { label: 'Contato', href: '#contato' }
  ];

  const handleNavClick = (e, href) => {
    e.preventDefault();
    const element = document.querySelector(href);
    if (element) {
      const offset = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  return (
    <footer className="footer">
      <div className="footer__container container">
        <div className="footer__grid">
          {/* Logo e Descrição */}
          <div className="footer__brand">
            <a href="#inicio" className="footer__logo" onClick={(e) => handleNavClick(e, '#inicio')}>
              <div className="footer__logo-mark">AD</div>
              <div className="footer__logo-text">
                <span className="footer__logo-name">ARTEFER DECOR</span>
              </div>
            </a>
            <p className="footer__description">
              Móveis que transformam ambientes através de design, qualidade e personalidade.
            </p>
            <div className="footer__location">
              <MapPin size={16} />
              <span>Ubá — Minas Gerais</span>
            </div>
          </div>

          {/* Links Rápidos */}
          <div className="footer__links">
            <h4 className="footer__title">Navegação</h4>
            <nav className="footer__nav">
              {navLinks.map((link) => (
                <a
                  key={link.label}
                  href={link.href}
                  className="footer__link"
                  onClick={(e) => handleNavClick(e, link.href)}
                >
                  {link.label}
                </a>
              ))}
            </nav>
          </div>

          {/* Contato */}
          <div className="footer__contact">
            <h4 className="footer__title">Contato</h4>
            <div className="footer__contact-list">
              <a
                href="tel:+5532998085068"
                className="footer__contact-item"
              >
                <Phone size={16} />
                <span>(32) 99808-5068</span>
              </a>
              <a
                href="mailto:contato@arteferdecor.com.br"
                className="footer__contact-item"
              >
                <Mail size={16} />
                <span>contato@arteferdecor.com.br</span>
              </a>
              <a
                href="https://instagram.com/artefer_decor_"
                target="_blank"
                rel="noopener noreferrer"
                className="footer__contact-item"
              >
                <Instagram size={16} />
                <span>@artefer_decor_</span>
              </a>
            </div>
          </div>

          {/* Endereço */}
          <div className="footer__address">
            <h4 className="footer__title">Visite-nos</h4>
            <address className="footer__address-text">
              Rua Realino Sebastião Firmiano<br />
              Ubá, MG<br />
              Brasil
            </address>
            <a
              href="https://wa.me/5532998085068?text=Olá!%20Gostaria%20de%20visitar%20o%20showroom%20da%20Artefer%20Decor"
              target="_blank"
              rel="noopener noreferrer"
              className="footer__visit-btn"
            >
              Agendar visita
            </a>
          </div>
        </div>

        {/* Bottom Bar */}
        <div className="footer__bottom">
          <p className="footer__copyright">
            © {currentYear} Artefer Decor. Todos os direitos reservados.
          </p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;

/* ============================================
   FOOTER - Minimalista e Profissional
   ============================================ */

.footer {
  background-color: var(--color-gray-900);
  color: var(--color-gray-300);
  padding: var(--space-16) 0 var(--space-8);
}

.footer__container {
  max-width: 1440px;
}

/* === GRID === */

.footer__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  margin-bottom: var(--space-12);
  padding-bottom: var(--space-12);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

@media (min-width: 640px) {
  .footer__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer__grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: var(--space-16);
  }
}

/* === BRAND === */

.footer__brand {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.footer__logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-2);
  width: fit-content;
}

.footer__logo-mark {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-off-white);
  color: var(--color-gray-900);
  font-family: var(--font-serif);
  font-size: var(--text-lg);
  font-weight: var(--font-semibold);
  letter-spacing: 0.02em;
}

.footer__logo-text {
  display: flex;
  flex-direction: column;
}

.footer__logo-name {
  font-family: var(--font-serif);
  font-size: var(--text-xl);
  font-weight: var(--font-semibold);
  color: var(--color-off-white);
  letter-spacing: 0.08em;
}

.footer__description {
  font-size: var(--text-sm);
  line-height: 1.6;
  color: var(--color-gray-400);
  max-width: 300px;
}

.footer__location {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--color-gray-400);
}

/* === LINKS === */

.footer__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.footer__title {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--color-off-white);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-2);
}

.footer__nav {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer__link {
  font-size: var(--text-sm);
  color: var(--color-gray-400);
  transition: color var(--transition-fast);
  width: fit-content;
}

.footer__link:hover {
  color: var(--color-off-white);
  opacity: 1;
}

/* === CONTATO === */

.footer__contact {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.footer__contact-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer__contact-item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--color-gray-400);
  transition: color var(--transition-fast);
  width: fit-content;
}

.footer__contact-item:hover {
  color: var(--color-off-white);
  opacity: 1;
}

/* === ENDEREÇO === */

.footer__address {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.footer__address-text {
  font-size: var(--text-sm);
  font-style: normal;
  line-height: 1.7;
  color: var(--color-gray-400);
}

.footer__visit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-3) var(--space-5);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--color-gray-900);
  background-color: var(--color-off-white);
  border: 1px solid var(--color-off-white);
  transition: all var(--transition-fast);
  width: fit-content;
}

.footer__visit-btn:hover {
  background-color: transparent;
  color: var(--color-off-white);
  opacity: 1;
}

/* === BOTTOM BAR === */

.footer__bottom {
  padding-top: var(--space-8);
  text-align: center;
}

.footer__copyright {
  font-size: var(--text-xs);
  color: var(--color-gray-500);
  letter-spacing: 0.02em;
}

/* === RESPONSIVO === */

@media (max-width: 639px) {
  .footer {
    padding: var(--space-12) 0 var(--space-6);
  }

  .footer__grid {
    gap: var(--space-10);
    margin-bottom: var(--space-10);
    padding-bottom: var(--space-10);
  }
}

