import React from 'react';
import { Instagram, MapPin, Mail, Phone } from 'lucide-react';
import './Footer.css';

const Footer = () => {
  const currentYear = new Date().getFullYear();

  const navLinks = [
    { label: 'Início', href: '#inicio' },
    { label: 'Móveis', href: '#moveis' },
    { label: 'Coleções', href: '#colecoes' },
    { label: 'Ambientes', href: '#ambientes' },
    { label: 'Sobre', href: '#sobre' },
    { label: 'Contato', href: '#contato' }
  ];

  const handleNavClick = (e, href) => {
    e.preventDefault();
    const element = document.querySelector(href);
    if (element) {
      const offset = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  return (
    <footer className="footer">
      <div className="footer__container container">
        <div className="footer__grid">
          {/* Logo e Descrição */}
          <div className="footer__brand">
            <a href="#inicio" className="footer__logo" onClick={(e) => handleNavClick(e, '#inicio')}>
              <div className="footer__logo-mark">AD</div>
              <div className="footer__logo-text">
                <span className="footer__logo-name">ARTEFER DECOR</span>
              </div>
            </a>
            <p className="footer__description">
              Móveis que transformam ambientes através de design, qualidade e personalidade.
            </p>
            <div className="footer__location">
              <MapPin size={16} />
              <span>Ubá — Minas Gerais</span>
            </div>
          </div>

          {/* Links Rápidos */}
          <div className="footer__links">
            <h4 className="footer__title">Navegação</h4>
            <nav className="footer__nav">
              {navLinks.map((link) => (
                <a
                  key={link.label}
                  href={link.href}
                  className="footer__link"
                  onClick={(e) => handleNavClick(e, link.href)}
                >
                  {link.label}
                </a>
              ))}
            </nav>
          </div>

          {/* Contato */}
          <div className="footer__contact">
            <h4 className="footer__title">Contato</h4>
            <div className="footer__contact-list">
              <a
                href="tel:+5532998085068"
                className="footer__contact-item"
              >
                <Phone size={16} />
                <span>(32) 99808-5068</span>
              </a>
              <a
                href="mailto:contato@arteferdecor.com.br"
                className="footer__contact-item"
              >
                <Mail size={16} />
                <span>contato@arteferdecor.com.br</span>
              </a>
              <a
                href="https://instagram.com/artefer_decor_"
                target="_blank"
                rel="noopener noreferrer"
                className="footer__contact-item"
              >
                <Instagram size={16} />
                <span>@artefer_decor_</span>
              </a>
            </div>
          </div>

          {/* Endereço */}
          <div className="footer__address">
            <h4 className="footer__title">Visite-nos</h4>
            <address className="footer__address-text">
              Rua Realino Sebastião Firmiano<br />
              Ubá, MG<br />
              Brasil
            </address>
            <a
              href="https://wa.me/5532998085068?text=Olá!%20Gostaria%20de%20visitar%20o%20showroom%20da%20Artefer%20Decor"
              target="_blank"
              rel="noopener noreferrer"
              className="footer__visit-btn"
            >
              Agendar visita
            </a>
          </div>
        </div>

        {/* Bottom Bar */}
        <div className="footer__bottom">
          <p className="footer__copyright">
            © {currentYear} Artefer Decor. Todos os direitos reservados.
          </p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;

