import React, { useEffect, useRef, useState } from 'react';
import './Destaque.css';

const Destaque = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="destaque section" id="destaque" ref={sectionRef}>
      <div className="destaque__container container">
        <div className={`destaque__grid ${isVisible ? 'destaque__grid--visible' : ''}`}>
          <div className="destaque__image">
            <img
              src="https://images.unsplash.com/photo-1595428774223-ef52624120d2?w=1200&q=80"
              alt="Aparador Artefer Decor"
              className="destaque__img"
            />
          </div>

          <div className="destaque__content">
            <h2 className="destaque__title">
              Design que marca presença
            </h2>
            <p className="destaque__text">
              Peças pensadas para transformar ambientes através de materiais,
              proporções e detalhes que fazem a diferença.
            </p>
            <p className="destaque__text">
              Na Artefer Decor, cada móvel é desenvolvido para valorizar
              o espaço onde vai viver. Madeira nobre, acabamentos cuidadosos
              e linhas que respeitam a arquitetura.
            </p>
            <a href="#sobre" className="destaque__btn">
              Conheça a Artefer
            </a>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Destaque;

