import React, { useEffect, useRef, useState } from 'react';
import { categorias } from '../data/content';
import './Categorias.css';

const Categorias = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="categorias section" id="moveis" ref={sectionRef}>
      <div className="categorias__container container">
        <div className={`categorias__header ${isVisible ? 'categorias__header--visible' : ''}`}>
          <h2 className="categorias__title">Explore nossas peças</h2>
        </div>

        <div className={`categorias__grid ${isVisible ? 'categorias__grid--visible' : ''}`}>
          {categorias.map((categoria, index) => (
            <article
              key={categoria.id}
              className="categorias__item"
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              <div className="categorias__image-wrapper">
                <img
                  src={categoria.imagem}
                  alt={categoria.nome}
                  className="categorias__image"
                  loading="lazy"
                />
                <div className="categorias__overlay">
                  <span className="categorias__explore">Explorar</span>
                </div>
              </div>
              <div className="categorias__info">
                <h3 className="categorias__name">{categoria.nome}</h3>
                <p className="categorias__description">{categoria.descricao}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Categorias;

/* ============================================
   CATEGORIAS - Grid Editorial
   ============================================ */

.categorias {
  background-color: var(--color-cream);
}

.categorias__header {
  text-align: center;
  margin-bottom: var(--space-12);
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

@media (min-width: 768px) {
  .categorias__header {
    margin-bottom: var(--space-16);
  }
}

.categorias__header--visible {
  opacity: 1;
  transform: translateY(0);
}

.categorias__title {
  font-family: var(--font-serif);
  font-size: var(--text-4xl);
  font-weight: var(--font-semibold);
  color: var(--color-gray-900);
  letter-spacing: -0.01em;
}

@media (min-width: 768px) {
  .categorias__title {
    font-size: var(--text-5xl);
  }
}

/* === GRID === */

.categorias__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
}

@media (min-width: 640px) {
  .categorias__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .categorias__grid {
    grid-template-columns: repeat(4, 1fr);
    gap: var(--space-6);
  }
}

/* === ITEM === */

.categorias__item {
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.categorias__grid--visible .categorias__item {
  opacity: 1;
  transform: translateY(0);
}

.categorias__image-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  background-color: var(--color-gray-200);
  margin-bottom: var(--space-4);
  cursor: pointer;
}

.categorias__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.categorias__overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.categorias__image-wrapper:hover .categorias__image {
  transform: scale(1.05);
}

.categorias__image-wrapper:hover .categorias__overlay {
  opacity: 1;
}

.categorias__explore {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--color-white);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--color-white);
}

/* === INFO === */

.categorias__info {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.categorias__name {
  font-family: var(--font-serif);
  font-size: var(--text-xl);
  font-weight: var(--font-medium);
  color: var(--color-gray-900);
}

.categorias__description {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  line-height: 1.6;
  color: var(--color-gray-600);
}

/* === RESPONSIVO === */

@media (max-width: 639px) {
  .categorias__grid {
    gap: var(--space-10);
  }

  .categorias__image-wrapper {
    aspect-ratio: 4 / 3;
  }
}

