const Colecoes = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="colecoes section" id="colecoes" ref={sectionRef}>
      <div className="colecoes__container container">
        <div className={`colecoes__header ${isVisible ? 'colecoes__header--visible' : ''}`}>
          <h2 className="colecoes__title">Coleções Artefer</h2>
          <p className="colecoes__subtitle">
            Cada coleção representa uma visão de design pensada para diferentes ambientes e estilos.
          </p>
        </div>

        <div className="colecoes__grid">
          {colecoes.map((colecao, index) => (
            <article
              key={colecao.id}
              className={`colecoes__item ${isVisible ? 'colecoes__item--visible' : ''}`}
              style={{ transitionDelay: `${index * 150}ms` }}
            >
              <div className="colecoes__image-container">
                <img
                  src={colecao.imagem}
                  alt={colecao.nome}
                  className="colecoes__image"
                  loading="lazy"
                />
                <div className="colecoes__image-overlay"></div>
              </div>
              <div className="colecoes__content">
                <span className="colecoes__tagline">{colecao.tagline}</span>
                <h3 className="colecoes__name">{colecao.nome}</h3>
                <p className="colecoes__description">{colecao.descricao}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Colecoes;

