    font-size: var(--text-3xl);
  }
}

.colecoes__description {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.7;
  color: var(--color-gray-600);
}

/* === RESPONSIVO === */

@media (max-width: 767px) {
  .colecoes__grid {
    gap: var(--space-16);
  }
}

