import { produtos } from '../data/content';
import './Produtos.css';

const Produtos = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="produtos section" id="produtos" ref={sectionRef}>
      <div className="produtos__container container">
        <div className={`produtos__header ${isVisible ? 'produtos__header--visible' : ''}`}>
          <h2 className="produtos__title">Peças que fazem a diferença</h2>
        </div>

        <div className="produtos__grid">
          {produtos.map((produto, index) => (
            <article
              key={produto.id}
              className={`produtos__card ${isVisible ? 'produtos__card--visible' : ''}`}
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              <div className="produtos__image-wrapper">
                <img
                  src={produto.imagem}
                  alt={produto.nome}
                  className="produtos__image"
                  loading="lazy"
                />
              </div>
              <div className="produtos__info">
                <div className="produtos__meta">
                  <span className="produtos__categoria">{produto.categoria}</span>
                  <span className="produtos__codigo">{produto.codigo}</span>
                </div>
                <h3 className="produtos__nome">{produto.nome}</h3>
                <p className="produtos__descricao">{produto.descricao}</p>
                <a
                  href={`https://wa.me/5532998085068?text=Olá!%20Gostaria%20de%20saber%20mais%20sobre%20${encodeURIComponent(produto.nome)}%20(${produto.codigo})`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="produtos__link"
                >
                  Ver detalhes
                </a>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Produtos;

/* ============================================
   PRODUTOS - Grid Elegante
   ============================================ */

.produtos {
  background-color: var(--color-off-white);
}

.produtos__header {
  text-align: center;
  margin-bottom: var(--space-16);
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.produtos__header--visible {
  opacity: 1;
  transform: translateY(0);
}

.produtos__title {
  font-family: var(--font-serif);
  font-size: var(--text-4xl);
