import React, { useEffect, useRef, useState } from 'react';
import { ambientes } from '../data/content';
import './Ambientes.css';

const Ambientes = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="ambientes section" id="ambientes" ref={sectionRef}>
      <div className="ambientes__container container">
        <div className={`ambientes__header ${isVisible ? 'ambientes__header--visible' : ''}`}>
          <h2 className="ambientes__title">Inspire-se</h2>
          <p className="ambientes__subtitle">
            Veja como nossas peças transformam diferentes ambientes
          </p>
        </div>

        <div className="ambientes__grid">
          {ambientes.map((ambiente, index) => (
            <article
              key={ambiente.id}
              className={`ambientes__card ${isVisible ? 'ambientes__card--visible' : ''}`}
              style={{ transitionDelay: `${index * 80}ms` }}
            >
              <div className="ambientes__image-container">
                <img
                  src={ambiente.imagem}
                  alt={ambiente.nome}
                  className="ambientes__image"
                  loading="lazy"
                />
                <div className="ambientes__overlay">
                  <div className="ambientes__text">
                    <h3 className="ambientes__nome">{ambiente.nome}</h3>
                    <p className="ambientes__descricao">{ambiente.descricao}</p>
