import React, { useEffect, useRef, useState } from 'react';
import './Sobre.css';

const Sobre = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="sobre section" id="sobre" ref={sectionRef}>
      <div className="sobre__container container">
        <div className={`sobre__grid ${isVisible ? 'sobre__grid--visible' : ''}`}>
          <div className="sobre__image">
            <img
              src="https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?w=1200&q=80"
              alt="Showroom Artefer Decor"
              className="sobre__img"
            />
          </div>

          <div className="sobre__content">
            <h2 className="sobre__title">Artefer Decor</h2>
            <p className="sobre__text sobre__text--lead">
              Mais do que móveis, criamos peças que participam da história de cada ambiente.
            </p>
            <p className="sobre__text">
              Em Ubá, Minas Gerais, a Artefer Decor une design, qualidade e
              personalidade para criar móveis capazes de transformar espaços.
            </p>
            <p className="sobre__text">
              Cada peça é pensada para valorizar o ambiente onde vai viver.
              Trabalhamos com madeira nobre, acabamentos cuidadosos e linhas
              que respeitam a arquitetura e a função.
            </p>
            <p className="sobre__text">
              Do projeto à entrega, nosso compromisso é com a qualidade,
              o atendimento próximo e o cuidado em cada detalhe.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Sobre;

/* ============================================
   SOBRE - Editorial, Institucional
   ============================================ */

.sobre {
  background-color: var(--color-cream);
}

.sobre__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  align-items: center;
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 1s cubic-bezier(0.4, 0, 0.2, 1),
              transform 1s cubic-bezier(0.4, 0, 0.2, 1);
}

@media (min-width: 1024px) {
  .sobre__grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-20);
  }
}

.sobre__grid--visible {
  opacity: 1;
  transform: translateY(0);
}

/* === IMAGEM === */

.sobre__image {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
}

@media (min-width: 768px) {
  .sobre__image {
    aspect-ratio: 5 / 4;
  }
}

@media (min-width: 1024px) {
  .sobre__image {
    order: 2;
  }
}

.sobre__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

/* === CONTEÚDO === */

.sobre__content {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

@media (min-width: 1024px) {
  .sobre__content {
    order: 1;
    padding-right: var(--space-8);
  }
}

