const iconMap = {
  design: Sparkles,
  quality: Award,
  star: Star,
  heart: Heart
};

const Diferenciais = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="diferenciais section" ref={sectionRef}>
      <div className="diferenciais__container container">
        <div className={`diferenciais__grid ${isVisible ? 'diferenciais__grid--visible' : ''}`}>
          {diferenciais.map((item, index) => {
            const Icon = iconMap[item.icone];
            return (
              <article
                key={item.id}
                className="diferenciais__item"
                style={{ transitionDelay: `${index * 100}ms` }}
              >
