import React, { useEffect, useRef, useState } from 'react';
import { Instagram as InstagramIcon } from 'lucide-react';
import { instagramFeed } from '../data/content';
import './Instagram.css';

const Instagram = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="instagram section" ref={sectionRef}>
      <div className="instagram__container container">
        <div className={`instagram__header ${isVisible ? 'instagram__header--visible' : ''}`}>
          <h2 className="instagram__title">Siga a Artefer Decor</h2>
          <a
            href="https://instagram.com/artefer_decor_"
            target="_blank"
            rel="noopener noreferrer"
            className="instagram__handle"
          >
            <InstagramIcon size={20} />
            <span>@artefer_decor_</span>
          </a>
        </div>

        <div className="instagram__grid">
          {instagramFeed.map((item, index) => (
            <a
              key={item.id}
              href="https://instagram.com/artefer_decor_"
              target="_blank"
              rel="noopener noreferrer"
              className={`instagram__item ${isVisible ? 'instagram__item--visible' : ''}`}
              style={{ transitionDelay: `${index * 80}ms` }}
            >
              <img
                src={item.imagem}
                alt={item.alt}
                className="instagram__image"
                loading="lazy"
              />
              <div className="instagram__overlay">
                <InstagramIcon size={32} strokeWidth={1.5} />
              </div>
            </a>
          ))}
        </div>

        <div className="instagram__cta">
          <a
            href="https://instagram.com/artefer_decor_"
            target="_blank"
            rel="noopener noreferrer"
            className="instagram__btn"
          >
            Ver Instagram
          </a>
        </div>
      </div>
    </section>
  );
};

export default Instagram;

/* ============================================
   INSTAGRAM - Editorial, Grid
   ============================================ */

.instagram {
  background-color: var(--color-off-white);
}

/* === HEADER === */

.instagram__header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-12);
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

@media (min-width: 768px) {
  .instagram__header {
    margin-bottom: var(--space-16);
  }
}

.instagram__header--visible {
  opacity: 1;
  transform: translateY(0);
}

.instagram__title {
  font-family: var(--font-serif);
  font-size: var(--text-4xl);
  font-weight: var(--font-semibold);
  color: var(--color-gray-900);
  letter-spacing: -0.01em;
}

@media (min-width: 768px) {
  .instagram__title {
    font-size: var(--text-5xl);
  }
}

.instagram__handle {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-sans);
  font-size: var(--text-lg);
  font-weight: var(--font-medium);
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
}

.instagram__handle:hover {
  color: var(--color-wood);
  opacity: 1;
}

/* === GRID === */

.instagram__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-2);
  margin-bottom: var(--space-12);
}

@media (min-width: 640px) {
  .instagram__grid {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--space-3);
  }
}

@media (min-width: 1024px) {
  .instagram__grid {
    grid-template-columns: repeat(6, 1fr);
    gap: var(--space-4);
  }
}

/* === ITEM === */

.instagram__item {
  position: relative;
  aspect-ratio: 1;
  overflow: hidden;
  background-color: var(--color-gray-200);
  opacity: 0;
  transform: scale(0.9);
  transition: opacity 0.5s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.instagram__item--visible {
  opacity: 1;
  transform: scale(1);
}

.instagram__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.instagram__overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  opacity: 0;
  transition: opacity var(--transition-base);
}

.instagram__item:hover .instagram__image {
  transform: scale(1.1);
}

.instagram__item:hover .instagram__overlay {
  opacity: 1;
}

/* === CTA === */

.instagram__cta {
  text-align: center;
}

.instagram__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4) var(--space-8);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  font-weight: var(--font-medium);
  color: var(--color-off-white);
  background-color: var(--color-gray-900);
  border: 1px solid var(--color-gray-900);
  transition: all var(--transition-base);
}

.instagram__btn:hover {
  background-color: transparent;
  color: var(--color-gray-900);
  opacity: 1;
}

import React, { useEffect, useRef, useState } from 'react';
import './CTA.css';

const CTA = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.3 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="cta" ref={sectionRef}>
      <div className="cta__background">
        <img
          src="https://images.unsplash.com/photo-1600210492493-0946911123ea?w=1920&q=80"
          alt="Ambiente Artefer Decor"
          className="cta__image"
        />
        <div className="cta__overlay"></div>
      </div>

      <div className="cta__container container">
        <div className={`cta__content ${isVisible ? 'cta__content--visible' : ''}`}>
          <h2 className="cta__title">
            Seu ambiente merece uma peça especial.
          </h2>
          <p className="cta__text">
            Fale com a Artefer Decor e descubra móveis pensados para transformar espaços.
          </p>
          <a
            href="https://wa.me/5532998085068?text=Olá!%20Gostaria%20de%20conhecer%20os%20móveis%20da%20Artefer%20Decor"
            target="_blank"
            rel="noopener noreferrer"
            className="cta__btn"
          >
            Falar pelo WhatsApp
          </a>
        </div>
      </div>
    </section>
  );
};

export default CTA;

/* ============================================
   CTA - Visual, Impactante
   ============================================ */

.cta {
  position: relative;
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--color-gray-900);
  padding: var(--space-20) 0;
}

@media (min-width: 768px) {
  .cta {
    min-height: 600px;
  }
}

/* === BACKGROUND === */

.cta__background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.cta__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.cta__overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(0, 0, 0, 0.7) 0%,
    rgba(0, 0, 0, 0.5) 100%
  );
}

/* === CONTEÚDO === */

.cta__container {
  position: relative;
  z-index: 2;
}

.cta__content {
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
