import React, { useState, useEffect, useRef } from 'react';
import { MapPin, Phone, Mail, Instagram } from 'lucide-react';
import './Contato.css';

const Contato = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [formData, setFormData] = useState({
    nome: '',
    telefone: '',
    email: '',
    mensagem: ''
  });
  const [status, setStatus] = useState({ type: '', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setStatus({ type: '', message: '' });

    // Validação básica
    if (!formData.nome || !formData.telefone || !formData.mensagem) {
      setStatus({
        type: 'error',
        message: 'Por favor, preencha todos os campos obrigatórios.'
      });
      setIsSubmitting(false);
      return;
    }

    // Simular envio (aqui você integraria com um backend real)
    setTimeout(() => {
      // Redirecionar para WhatsApp com a mensagem
      const mensagemWhatsApp = `Olá! Meu nome é ${formData.nome}.%0A%0ATelefone: ${formData.telefone}%0AEmail: ${formData.email || 'Não informado'}%0A%0AMensagem:%0A${formData.mensagem}`;
      window.open(`https://wa.me/5532998085068?text=${mensagemWhatsApp}`, '_blank');

      setStatus({
        type: 'success',
        message: 'Redirecionando para o WhatsApp...'
      });

      // Limpar formulário
      setFormData({
        nome: '',
        telefone: '',
        email: '',
        mensagem: ''
      });

      setIsSubmitting(false);
    }, 500);
  };

  return (
    <section className="contato section" id="contato" ref={sectionRef}>
      <div className="contato__container container">
        <div className={`contato__grid ${isVisible ? 'contato__grid--visible' : ''}`}>
          {/* Informações */}
          <div className="contato__info">
            <h2 className="contato__title">Vamos criar algo especial?</h2>

            <div className="contato__details">
              <div className="contato__detail">
                <span className="contato__label">Artefer Decor</span>
                <div className="contato__value">
                  <MapPin size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  Rua Realino Sebastião Firmiano<br />
                  Ubá, MG<br />
                  Brasil
                </div>
              </div>

              <div className="contato__detail">
                <span className="contato__label">Telefone</span>
                <a href="tel:+5532998085068" className="contato__value contato__link">
                  <Phone size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  (32) 99808-5068
                </a>
              </div>

              <div className="contato__detail">
                <span className="contato__label">E-mail</span>
                <a href="mailto:contato@arteferdecor.com.br" className="contato__value contato__link">
                  <Mail size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  contato@arteferdecor.com.br
                </a>
              </div>

              <div className="contato__detail">
                <span className="contato__label">Instagram</span>
                <a
                  href="https://instagram.com/artefer_decor_"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="contato__value contato__link"
                >
                  <Instagram size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  @artefer_decor_
                </a>
              </div>
            </div>
          </div>

          {/* Formulário */}
          <form className="contato__form" onSubmit={handleSubmit}>
            <h3 className="contato__form-title">Envie uma mensagem</h3>

            {status.message && (
              <div className={`contato__message contato__message--${status.type}`}>
                {status.message}
              </div>
            )}

            <div className="contato__field">
              <label htmlFor="nome" className="contato__field-label">
                Nome *
              </label>
              <input
                type="text"
                id="nome"
                name="nome"
                value={formData.nome}
                onChange={handleChange}
                className="contato__input"
                placeholder="Seu nome"
                required
              />
            </div>

            <div className="contato__field">
              <label htmlFor="telefone" className="contato__field-label">
                Telefone *
              </label>
              <input
                type="tel"
                id="telefone"
                name="telefone"
                value={formData.telefone}
                onChange={handleChange}
                className="contato__input"
                placeholder="(32) 99999-9999"
                required
              />
