/* ============================================
   CONTATO - Elegante, Funcional
   ============================================ */

.contato {
  background-color: var(--color-white);
}

.contato__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-16);
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 1s cubic-bezier(0.4, 0, 0.2, 1),
              transform 1s cubic-bezier(0.4, 0, 0.2, 1);
}

@media (min-width: 1024px) {
  .contato__grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-20);
  }
}

.contato__grid--visible {
  opacity: 1;
  transform: translateY(0);
}

/* === INFO === */

.contato__info {
  display: flex;
  flex-direction: column;
  gap: var(--space-8);
}

.contato__title {
  font-family: var(--font-serif);
  font-size: var(--text-4xl);
  font-weight: var(--font-semibold);
  line-height: 1.2;
  color: var(--color-gray-900);
  letter-spacing: -0.01em;
}

@media (min-width: 768px) {
  .contato__title {
    font-size: var(--text-5xl);
  }
}

.contato__details {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

.contato__detail {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.contato__label {
  font-family: var(--font-sans);
  font-size: var(--text-xs);
  font-weight: var(--font-semibold);
  color: var(--color-wood);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.contato__value {
  font-family: var(--font-sans);
  font-size: var(--text-lg);
  color: var(--color-gray-800);
  line-height: 1.6;
}

.contato__link {
  color: var(--color-gray-800);
  transition: color var(--transition-fast);
}

.contato__link:hover {
  color: var(--color-wood);
  opacity: 1;
}

/* === FORM === */

.contato__form {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
  padding: var(--space-10);
  background-color: var(--color-cream);
}

@media (min-width: 768px) {
  .contato__form {
    padding: var(--space-12);
  }
}

.contato__form-title {
  font-family: var(--font-serif);
  font-size: var(--text-2xl);
  font-weight: var(--font-medium);
  color: var(--color-gray-900);
  margin-bottom: var(--space-2);
}

.contato__field {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.contato__field-label {
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: var(--font-medium);
  color: var(--color-gray-700);
}

.contato__input,
.contato__textarea {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  padding: var(--space-4);
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-300);
  color: var(--color-gray-900);
  transition: border-color var(--transition-fast);
}

.contato__input:focus,
.contato__textarea:focus {
  outline: none;
  border-color: var(--color-wood);
}

.contato__input::placeholder,
.contato__textarea::placeholder {
  color: var(--color-gray-400);
}

.contato__textarea {
  min-height: 140px;
  resize: vertical;
}

.contato__submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4) var(--space-8);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  font-weight: var(--font-medium);
  color: var(--color-off-white);
  background-color: var(--color-gray-900);
  border: 1px solid var(--color-gray-900);
  transition: all var(--transition-base);
  cursor: pointer;
  width: 100%;
}

.contato__submit:hover {
  background-color: transparent;
  color: var(--color-gray-900);
}

.contato__submit:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* === MENSAGEM === */

.contato__message {
  padding: var(--space-4);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  border-radius: var(--radius-sm);
  text-align: center;
}

.contato__message--success {
  background-color: #d4edda;
  color: #155724;
  border: 1px solid #c3e6cb;
}

.contato__message--error {
  background-color: #f8d7da;
  color: #721c24;
  border: 1px solid #f5c6cb;
}

/* === RESPONSIVO === */

@media (max-width: 767px) {
  .contato__grid {
    gap: var(--space-12);
  }

  .contato__title {
    font-size: var(--text-3xl);
  }

  .contato__form {
    padding: var(--space-8);
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { MapPin, Phone, Mail, Instagram } from 'lucide-react';
import './Contato.css';

const Contato = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [formData, setFormData] = useState({
    nome: '',
    telefone: '',
    email: '',
    mensagem: ''
  });
  const [status, setStatus] = useState({ type: '', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setStatus({ type: '', message: '' });

    // Validação básica
    if (!formData.nome || !formData.telefone || !formData.mensagem) {
      setStatus({
        type: 'error',
        message: 'Por favor, preencha todos os campos obrigatórios.'
      });
      setIsSubmitting(false);
      return;
    }

    // Simular envio (aqui você integraria com um backend real)
    setTimeout(() => {
      // Redirecionar para WhatsApp com a mensagem
      const mensagemWhatsApp = `Olá! Meu nome é ${formData.nome}.%0A%0ATelefone: ${formData.telefone}%0AEmail: ${formData.email || 'Não informado'}%0A%0AMensagem:%0A${formData.mensagem}`;
      window.open(`https://wa.me/5532998085068?text=${mensagemWhatsApp}`, '_blank');

      setStatus({
        type: 'success',
        message: 'Redirecionando para o WhatsApp...'
      });

      // Limpar formulário
      setFormData({
        nome: '',
        telefone: '',
        email: '',
        mensagem: ''
      });

      setIsSubmitting(false);
    }, 500);
  };

  return (
    <section className="contato section" id="contato" ref={sectionRef}>
      <div className="contato__container container">
        <div className={`contato__grid ${isVisible ? 'contato__grid--visible' : ''}`}>
          {/* Informações */}
          <div className="contato__info">
            <h2 className="contato__title">Vamos criar algo especial?</h2>

            <div className="contato__details">
              <div className="contato__detail">
                <span className="contato__label">Artefer Decor</span>
                <div className="contato__value">
                  <MapPin size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  Rua Realino Sebastião Firmiano<br />
                  Ubá, MG<br />
                  Brasil
                </div>
              </div>

              <div className="contato__detail">
                <span className="contato__label">Telefone</span>
                <a href="tel:+5532998085068" className="contato__value contato__link">
                  <Phone size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  (32) 99808-5068
                </a>
              </div>

              <div className="contato__detail">
                <span className="contato__label">E-mail</span>
                <a href="mailto:contato@arteferdecor.com.br" className="contato__value contato__link">
                  <Mail size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  contato@arteferdecor.com.br
                </a>
              </div>

              <div className="contato__detail">
                <span className="contato__label">Instagram</span>
                <a
                  href="https://instagram.com/artefer_decor_"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="contato__value contato__link"
                >
                  <Instagram size={16} style={{ display: 'inline', marginRight: '8px' }} />
                  @artefer_decor_
                </a>
              </div>
            </div>
          </div>

          {/* Formulário */}
          <form className="contato__form" onSubmit={handleSubmit}>
            <h3 className="contato__form-title">Envie uma mensagem</h3>

            {status.message && (
              <div className={`contato__message contato__message--${status.type}`}>
                {status.message}
              </div>
            )}

            <div className="contato__field">
              <label htmlFor="nome" className="contato__field-label">
                Nome *
              </label>
              <input
                type="text"
                id="nome"
                name="nome"
                value={formData.nome}
                onChange={handleChange}
                className="contato__input"
                placeholder="Seu nome"
                required
              />
            </div>

            <div className="contato__field">
              <label htmlFor="telefone" className="contato__field-label">
                Telefone *
              </label>
              <input
                type="tel"
                id="telefone"
                name="telefone"
                value={formData.telefone}
                onChange={handleChange}
                className="contato__input"
                placeholder="(32) 99999-9999"
                required
              />
            </div>

            <div className="contato__field">
              <label htmlFor="email" className="contato__field-label">
                E-mail
              </label>
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="contato__input"
                placeholder="seu@email.com"
              />
            </div>

            <div className="contato__field">
              <label htmlFor="mensagem" className="contato__field-label">
                Mensagem *
              </label>
              <textarea
                id="mensagem"
                name="mensagem"
                value={formData.mensagem}
                onChange={handleChange}
                className="contato__textarea"
                placeholder="Conte-nos sobre seu projeto ou dúvida"
                required
              ></textarea>
            </div>

            <button
              type="submit"
              className="contato__submit"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Enviando...' : 'Enviar mensagem'}
            </button>
          </form>
        </div>
      </div>
    </section>
  );
};

export default Contato;

